bool t2 = false;
try { a.Deposit(-100m); } catch (ArgumentException) { t2 = true; }
bool t3 = false;
try { a.Withdraw(999m); } catch (InvalidOperationException) { t3 = true; }
bool t4 = false;
try { a.Withdraw(-10m); } catch (ArgumentException) { t4 = true; }
